-- SANDARBH 2.0 base schema. PostgreSQL 15+ / Supabase.
create extension if not exists pgcrypto with schema extensions;
do $$ begin create type app_role as enum ('super_admin','chief_editor','managing_editor','reporter','researcher','fact_checker','content_editor','social_media_manager','reader'); exception when duplicate_object then null; end $$;
do $$ begin create type article_status as enum ('draft','research','fact_check','editorial_review','pending_chief','scheduled','published','rejected','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type block_type as enum ('subject','background','facts','claims','evidence','primary_sources','contested','perspectives','fact_check','editorial_comment'); exception when duplicate_object then null; end $$;
do $$ begin create type verification_status as enum ('verified','official_statement','attributed_claim','expert_interpretation','editorial_opinion','unverified','unresolved'); exception when duplicate_object then null; end $$;
do $$ begin create type source_type as enum ('government','court','parliament','official_document','press_release','interview','research_paper','academic','news_org','field_report','social','other'); exception when duplicate_object then null; end $$;
do $$ begin create type social_platform as enum ('youtube','facebook','instagram','x','threads','telegram','whatsapp','linkedin'); exception when duplicate_object then null; end $$;
do $$ begin create type post_status as enum ('draft','ai_generated','editor_review','approved','scheduled','published','failed','correction_required','archived','sensitive_review_required'); exception when duplicate_object then null; end $$;

create table if not exists roles(name app_role primary key,description text not null);
create table if not exists permissions(id bigint generated always as identity primary key,role app_role not null references roles(name) on delete cascade,permission text not null,unique(role,permission));
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role app_role not null default 'reader' references roles(name),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists categories(id bigint generated always as identity primary key,slug text unique not null,name_hi text not null,name_en text,parent_id bigint references categories(id) on delete set null,sort_order int not null default 0);
create table if not exists tags(id bigint generated always as identity primary key,slug text unique not null,name text not null);
create table if not exists articles(id uuid primary key default gen_random_uuid(),slug text unique not null,headline_hi text not null,headline_en text,summary_hi text,category_id bigint references categories(id) on delete set null,author_id uuid references profiles(id) on delete set null,status article_status not null default 'draft',risk_level text not null default 'normal' check(risk_level in ('normal','high')),ai_assistance text not null default 'none' check(ai_assistance in ('none','assisted','generated')),hero_image_path text,scheduled_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists article_blocks(id bigint generated always as identity primary key,article_id uuid not null references articles(id) on delete cascade,block_type block_type not null,content jsonb not null default '{}',verification verification_status,sort_order int not null default 0);
create index if not exists article_blocks_order_idx on article_blocks(article_id,sort_order);
create table if not exists article_tags(article_id uuid references articles(id) on delete cascade,tag_id bigint references tags(id) on delete cascade,primary key(article_id,tag_id));
create table if not exists sources(id bigint generated always as identity primary key,title text not null,source_type source_type not null,url text,publisher text,published_on date,retrieved_at timestamptz not null default now(),reliability_score numeric(3,2) check(reliability_score between 0 and 1),verification verification_status not null default 'unverified',uploaded_by uuid references profiles(id),storage_path text);
create table if not exists research_sessions(id uuid primary key default gen_random_uuid(),topic text not null,created_by uuid references profiles(id),status text not null default 'running' check(status in ('running','completed','failed')),result jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists research_documents(id bigint generated always as identity primary key,session_id uuid references research_sessions(id) on delete cascade,source_id bigint references sources(id) on delete set null,file_path text not null,extracted_text text,ocr_done boolean not null default false,created_at timestamptz not null default now());
create table if not exists article_sources(article_id uuid references articles(id) on delete cascade,source_id bigint references sources(id) on delete cascade,note text,primary key(article_id,source_id));
create table if not exists fact_checks(id bigint generated always as identity primary key,article_id uuid not null references articles(id) on delete cascade,claim_text text not null,verdict verification_status not null default 'unresolved',both_sides jsonb not null default '{}',checked_by uuid references profiles(id),checked_at timestamptz,notes text);
create table if not exists editorial_reviews(id bigint generated always as identity primary key,article_id uuid not null references articles(id) on delete cascade,reviewer_id uuid not null references profiles(id),decision text not null check(decision in ('comment','revise','approve','reject')),comment text,created_at timestamptz not null default now());
create table if not exists approvals(id bigint generated always as identity primary key,article_id uuid not null references articles(id) on delete cascade,approver_id uuid not null references profiles(id),role app_role not null,decision text not null check(decision in ('approved','rejected')),reason text,created_at timestamptz not null default now());
create table if not exists revisions(id bigint generated always as identity primary key,article_id uuid not null references articles(id) on delete cascade,snapshot jsonb not null,saved_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists social_posts(id bigint generated always as identity primary key,article_id uuid references articles(id) on delete cascade,platform social_platform not null,content_type text not null,native_text text not null,media_paths text[] not null default '{}',link_url text,status post_status not null default 'draft',platform_post_id text,error_log text,scheduled_at timestamptz,published_at timestamptz,created_by uuid references profiles(id),approved_by uuid references profiles(id));
create table if not exists publication_logs(id bigint generated always as identity primary key,post_id bigint references social_posts(id) on delete cascade,action text not null,detail jsonb not null default '{}',actor_id uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists advertisements(id bigint generated always as identity primary key,slot text not null,provider text not null default 'adsterra',zone_id text,custom_html text,is_sponsored boolean not null default false,disclosure_label text not null default 'विज्ञापन',active boolean not null default true,starts_at timestamptz,ends_at timestamptz);
create table if not exists analytics(id bigint generated always as identity primary key,metric text not null,dimension jsonb not null default '{}',value numeric not null,recorded_at timestamptz not null default now());
create index if not exists analytics_metric_time_idx on analytics(metric,recorded_at);
create table if not exists audit_logs(id bigint generated always as identity primary key,actor_id uuid,action text not null,entity text not null,entity_id text,before jsonb,after jsonb,ip inet,created_at timestamptz not null default now());
create index if not exists audit_entity_idx on audit_logs(entity,entity_id);

create or replace function current_app_role() returns app_role language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid() $$;
create or replace function is_staff() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(current_app_role()<>'reader',false) $$;
create or replace function has_role(r app_role[]) returns boolean language sql stable security definer set search_path=public as $$ select current_app_role()=any(r) $$;
create or replace function log_audit(p_action text,p_entity text,p_entity_id text,p_before jsonb default null,p_after jsonb default null) returns void language plpgsql security definer set search_path=public as $$ begin insert into audit_logs(actor_id,action,entity,entity_id,before,after,ip) values(auth.uid(),p_action,p_entity,p_entity_id,p_before,p_after,inet_client_addr()); end $$;
create or replace function article_revision_trigger() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='UPDATE' then insert into revisions(article_id,snapshot,saved_by) values(old.id,to_jsonb(old),auth.uid()); perform log_audit('article.update','article',old.id::text,to_jsonb(old),to_jsonb(new)); if new.status='published' and old.status is distinct from 'published' and not exists(select 1 from approvals a where a.article_id=new.id and a.role in ('chief_editor','super_admin') and a.decision='approved') then raise exception 'PUBLISH_REQUIRES_CHIEF_APPROVAL'; end if; if new.status='published' and old.status is distinct from 'published' then new.published_at=now(); end if; return new; elsif tg_op='INSERT' then perform log_audit('article.create','article',new.id::text,null,to_jsonb(new)); return new; end if; return null; end $$;
drop trigger if exists trg_article_revision on articles;
create trigger trg_article_revision before insert or update on articles for each row execute function article_revision_trigger();
create or replace function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),'reader'); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();

alter table profiles enable row level security; alter table articles enable row level security; alter table article_blocks enable row level security; alter table article_tags enable row level security; alter table categories enable row level security; alter table tags enable row level security; alter table sources enable row level security; alter table research_sessions enable row level security; alter table research_documents enable row level security; alter table article_sources enable row level security; alter table fact_checks enable row level security; alter table editorial_reviews enable row level security; alter table approvals enable row level security; alter table revisions enable row level security; alter table social_posts enable row level security; alter table publication_logs enable row level security; alter table advertisements enable row level security; alter table analytics enable row level security; alter table audit_logs enable row level security; alter table roles enable row level security; alter table permissions enable row level security;
create policy "public read roles" on roles for select using(true);
create policy "public read permissions" on permissions for select using(true);
create policy "profiles read own or staff" on profiles for select using(auth.uid()=id or is_staff());
create policy "profiles update own" on profiles for update using(auth.uid()=id) with check(auth.uid()=id and role=(select role from profiles where id=auth.uid()));
create policy "articles public published" on articles for select using(status='published' or is_staff() or author_id=auth.uid());
create policy "articles staff insert" on articles for insert with check(is_staff() and (author_id=auth.uid() or author_id is null));
create policy "articles staff update" on articles for update using(is_staff()) with check(is_staff());
create policy "articles author delete draft" on articles for delete using(author_id=auth.uid() and status='draft');
create policy "blocks follow article" on article_blocks for all using(exists(select 1 from articles a where a.id=article_id and (a.status='published' or is_staff())));
create policy "article_tags follow article" on article_tags for all using(exists(select 1 from articles a where a.id=article_id and (a.status='published' or is_staff())));
create policy "article_sources staff" on article_sources for all using(is_staff()) with check(is_staff());
create policy "categories public read" on categories for select using(true);
create policy "tags public read" on tags for select using(true);
create policy "sources public verified" on sources for select using(verification in ('verified','official_statement') or is_staff());
create policy "sources staff write" on sources for all using(is_staff()) with check(is_staff());
create policy "research sessions staff" on research_sessions for all using(is_staff()) with check(is_staff());
create policy "research docs staff" on research_documents for all using(is_staff()) with check(is_staff());
create policy "fact_checks staff" on fact_checks for all using(is_staff()) with check(is_staff());
create policy "editorial_reviews staff" on editorial_reviews for all using(is_staff()) with check(is_staff());
create policy "approvals staff read" on approvals for select using(is_staff());
create policy "approvals chief insert" on approvals for insert with check(has_role(array['chief_editor','super_admin']::app_role[]) and approver_id=auth.uid());
create policy "revisions staff" on revisions for select using(is_staff());
create policy "social_posts staff" on social_posts for all using(is_staff()) with check(is_staff());
create policy "publication_logs staff read" on publication_logs for select using(is_staff());
create policy "ads public active" on advertisements for select using(active=true or is_staff());
create policy "ads staff write" on advertisements for all using(is_staff()) with check(is_staff());
create policy "analytics staff" on analytics for select using(is_staff());
create policy "audit staff read" on audit_logs for select using(is_staff());
create policy "audit insert via definer" on audit_logs for insert with check(true);
